#!/usr/bin/env bash
# Applied by "cka verify". Generated by Quick Create.
set -euo pipefail

# Question 2: Unhealthy worker
case "${Q2_FAULT}" in
  kubelet-stopped) ;;
  containerd-stopped) ;;
  kubelet-binary-path) ;;
  cordoned)
    kubectl uncordon "${Q2_NODE}"
    ;;
  stray-taint)
    kubectl taint node "${Q2_NODE}" maintenance-
    ;;
esac

case "${Q2_FAULT}" in
  kubelet-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    ;;
  containerd-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    ;;
  kubelet-binary-path)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    ;;
  cordoned) ;;
  stray-taint) ;;
esac

# Question 3: Deployment ${Q3_NAME}
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: "${Q3_NAME}"
  namespace: "${Q3_NS}"
  labels:
    app: "${Q3_NAME}"
spec:
  replicas: ${Q3_REPLICAS}
  selector:
    matchLabels:
      app: "${Q3_NAME}"
  template:
    metadata:
      labels:
        app: "${Q3_NAME}"
    spec:
      containers:
        - name: app
          image: "${Q3_IMAGE}"
          ports:
            - containerPort: 80
---
apiVersion: v1
kind: Service
metadata:
  name: "${Q3_NAME}"
  namespace: "${Q3_NS}"
spec:
  type: "${Q3_EXPOSE_TYPE}"
  selector:
    app: "${Q3_NAME}"
  ports:
    - port: ${Q3_EXPOSE_PORT}
      targetPort: 80
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: "${Q3_NAME}"
  namespace: "${Q3_NS}"
spec:
  ingressClassName: traefik
  rules:
    - host: "${Q3_INGRESS_SUB}.${Q3_NS}.lab"
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: "${Q3_NAME}"
                port:
                  number: ${Q3_EXPOSE_PORT}
EOF
kubectl -n "${Q3_NS}" rollout status "deployment/${Q3_NAME}" --timeout=240s
for _ in $(seq 1 30); do [[ "$(curl -s -m 5 -o /dev/null -w '%{http_code}' -H 'Host: ${Q3_INGRESS_SUB}.${Q3_NS}.lab' http://controlplane:30080/)" == 200 ]] && break; sleep 2; done
